type DependabotCreateOrUpdateRepoSecretParams struct {
	Owner          string
	Repo           string
	SecretName     string
	EncryptedValue *string
	KeyId          *string
}

// DependabotCreateOrUpdateRepoSecret creates or updates a repository secret with an encrypted value. Encrypt your secret using [LibSodium](https://libsodium.gitbook.io/doc/bindings_for_other_languages). For more information, see "[Encrypting secrets for the REST API](https://docs.github.com/rest/guides/encrypting-secrets-for-the-rest-api)." OAuth app tokens and personal access tokens (classic) need the `repo` scope to use this endpoint.
//
// Parameters:
//
//	owner: The account owner of the repository. The name is not case sensitive.
//	repo: The name of the repository without the `.git` extension. The name is
//	not case sensitive.
//	secretName: The name of the secret.
//	encryptedValue: Value for your secret, encrypted with
//	[LibSodium](https://libsodium.gitbook.io/doc/bindings_for_other_languages)
//	using the public key retrieved from the [Get a repository public
//	key](https://docs.github.com/rest/dependabot/secrets#get-a-repository-public
//	-key) endpoint.
//	keyId: ID of the key you used to encrypt the secret.
func DependabotCreateOrUpdateRepoSecret(ctx context.Context, clientConfig ClientConfig, params DependabotCreateOrUpdateRepoSecretParams, opts ...RequestOption) (*EmptyObject, error) {
	owner := params.Owner
	repo := params.Repo
	secretName := params.SecretName
	encryptedValue := params.EncryptedValue
	keyId := params.KeyId

	if encryptedValue != nil {
		if err := ValidatePattern("encrypted_value", *encryptedValue, "^(?:[A-Za-z0-9+/]{4})*(?:[A-Za-z0-9+/]{2}==|[A-Za-z0-9+/]{3}=|[A-Za-z0-9+/]{4})$"); err != nil {
			return nil, err
		}
	}

	resp, err := DoCfg[EmptyObject](ctx, &clientConfig, "PUT", fmt.Sprintf("/repos/%s/%s/dependabot/secrets/%s", EncodePathSegment(owner), EncodePathSegment(repo), EncodePathSegment(secretName)), &RequestOpts{
		Body: map[string]any{
			"encrypted_value": encryptedValue,
			"key_id":          keyId,
		},
		OperationID: "DependabotCreateOrUpdateRepoSecret",
		Options:     opts,
	})
	if err != nil {
		return nil, err
	}
	return &resp.Data, nil
}

